package com.taskmanager.service;
import com.taskmanager.dto.*;import com.taskmanager.entity.*;import com.taskmanager.enums.*;import com.taskmanager.repository.*;import jakarta.persistence.EntityNotFoundException;import org.springframework.stereotype.Service;import java.util.*;
@Service public class TaskService {private final TaskRepository tasks;private final UserRepository users;public TaskService(TaskRepository t,UserRepository u){tasks=t;users=u;}public List<TaskResponse> list(String email,TaskStatus s,TaskPriority p,String q){Long id=user(email).getId();return tasks.filtered(id,s,p,q==null||q.isBlank()?null:q.trim()).stream().map(TaskResponse::from).toList();}public TaskResponse get(String email,Long id){return TaskResponse.from(owned(email,id));}public TaskResponse create(String email,TaskRequest r){return TaskResponse.from(tasks.save(new Task(r.title().trim(),r.description(),r.dueDate(),r.status(),r.priority(),user(email))));}public TaskResponse update(String email,Long id,TaskRequest r){Task t=owned(email,id);t.update(r.title().trim(),r.description(),r.dueDate(),r.status(),r.priority());return TaskResponse.from(tasks.save(t));}public void delete(String email,Long id){tasks.delete(owned(email,id));}public Map<String,Long> stats(String email){Long id=user(email).getId();return Map.of("total",tasks.countByOwnerId(id),"pending",tasks.countByOwnerIdAndStatus(id,TaskStatus.PENDING),"inProgress",tasks.countByOwnerIdAndStatus(id,TaskStatus.IN_PROGRESS),"completed",tasks.countByOwnerIdAndStatus(id,TaskStatus.COMPLETED));}private User user(String e){return users.findByEmail(e).orElseThrow(()->new EntityNotFoundException("User not found"));}private Task owned(String e,Long id){return tasks.findByIdAndOwnerId(id,user(e).getId()).orElseThrow(()->new EntityNotFoundException("Task not found"));}}
